                grid_row = r_out + sec_idx * 3
                val = grid[grid_row][c]
                if val != 0:
                    nonzero_by_sec.append((sec_idx, val))

            if not nonzero_by_sec:
                result[r_out][c] = 0
            else:
                # Check if BOTH section 2 and section 3 are present
                has_sec2 = any(s == 2 for s, v in nonzero_by_sec)
                has_sec3 = any(s == 3 for s, v in nonzero_by_sec)

                if has_sec2 and has_sec3:
                    # Get values from sec 2 and sec 3
                    sec2_val = next(v for s, v in nonzero_by_sec if s == 2)
                    sec3_val = next(v for s, v in nonzero_by_sec if s == 3)
                    result[r_out][c] = max(sec2_val, sec3_val)
                else:
                    # Use MIN of all non-zero sections
                    result[r_out][c] = min(v for s, v in nonzero_by_sec)

